# exercises_b.py -- data shaping (exercises 4-6)
import json
import re
from typing import Any, Callable, Hashable, Iterable, TypeVar

T = TypeVar("T")
K = TypeVar("K", bound=Hashable)


def group_by(items: Iterable[T], key: Callable[[T], K]) -> dict[K, list[T]]:
    """4. Group items by key(item); each group keeps input order."""
    groups: dict[K, list[T]] = {}
    for item in items:
        groups.setdefault(key(item), []).append(item)
    return groups


def chunk_tokens(tokens: list[str], size: int, overlap: int) -> list[list[str]]:
    """5. Sliding window: windows of `size`, each starting `size - overlap` after the last."""
    if size <= 0:
        raise ValueError("size must be positive")
    if not 0 <= overlap < size:
        raise ValueError("overlap must satisfy 0 <= overlap < size")
    step = size - overlap
    chunks: list[list[str]] = []
    for start in range(0, len(tokens), step):
        chunks.append(tokens[start:start + size])
        if start + size >= len(tokens):  # this window already reached the end
            break
    return chunks


class ModelOutputError(ValueError):
    """Raised when model output cannot be turned into a valid object."""


_FENCE = re.compile(r"^```[a-zA-Z]*\s*|\s*```$")


def parse_model_json(raw: str, required: dict[str, type]) -> dict[str, Any]:
    """6. Parse JSON that may be wrapped in prose or ``` fences, then validate fields."""
    text = _FENCE.sub("", raw.strip())
    start, end = text.find("{"), text.rfind("}")
    if start == -1 or end <= start:
        raise ModelOutputError("no JSON object found")
    try:
        data = json.loads(text[start:end + 1])
    except json.JSONDecodeError as exc:
        raise ModelOutputError(f"invalid JSON: {exc.msg}") from exc
    for name, typ in required.items():
        if name not in data:
            raise ModelOutputError(f"missing field: {name}")
        value = data[name]
        # bool is a subclass of int in Python: reject True/False where int is wanted.
        if not isinstance(value, typ) or (typ is int and isinstance(value, bool)):
            raise ModelOutputError(f"field {name} should be {typ.__name__}")
    return data


def test_b() -> None:
    assert group_by(["apple", "avocado", "bean"], key=lambda s: s[0]) == {"a": ["apple", "avocado"], "b": ["bean"]}
    assert group_by([], key=len) == {}
    toks = list("abcdefghij")  # 10 tokens
    c = chunk_tokens(toks, size=4, overlap=1)  # step 3 -> starts 0, 3, 6
    assert c == [list("abcd"), list("defg"), list("ghij")]
    assert chunk_tokens(toks[:3], 4, 1) == [list("abc")]  # shorter than one window
    assert chunk_tokens([], 4, 1) == []
    assert chunk_tokens(toks, 5, 0) == [list("abcde"), list("fghij")]  # no trailing duplicate window
    for bad in [(0, 0), (4, 4), (4, -1)]:
        try:
            chunk_tokens(toks, *bad)
            raise AssertionError("should raise")
        except ValueError:
            pass
    req = {"label": str, "score": int}
    assert parse_model_json('{"label": "ok", "score": 3}', req)["score"] == 3
    fenced = 'Sure! Here you go:\n```json\n{"label": "ok", "score": 3}\n```'
    assert parse_model_json(fenced, req)["label"] == "ok"
    for bad_raw in ["no json", '{"label": "ok"}', '{"label": "ok", "score": true}', '{"label": "ok", "score": }']:
        try:
            parse_model_json(bad_raw, req)
            raise AssertionError("should raise")
        except ModelOutputError:
            pass

# exercises_c.py -- reliability tools (exercises 7-8)
import functools
import time
from collections import OrderedDict
from typing import Callable, Generic, Hashable, ParamSpec, TypeVar

P = ParamSpec("P")
R = TypeVar("R")
K = TypeVar("K", bound=Hashable)
V = TypeVar("V")


def retry(
    attempts: int = 3,
    base_delay: float = 0.5,
    exceptions: tuple[type[BaseException], ...] = (Exception,),
    sleep: Callable[[float], None] = time.sleep,  # injectable so tests do not wait
) -> Callable[[Callable[P, R]], Callable[P, R]]:
    """7. Retry on `exceptions` with exponential backoff: base, 2*base, 4*base ..."""
    if attempts < 1:
        raise ValueError("attempts must be >= 1")

    def decorator(fn: Callable[P, R]) -> Callable[P, R]:
        @functools.wraps(fn)  # keep __name__ and __doc__ of the wrapped function
        def wrapper(*args: P.args, **kwargs: P.kwargs) -> R:
            for attempt in range(attempts):
                try:
                    return fn(*args, **kwargs)
                except exceptions:
                    if attempt == attempts - 1:
                        raise  # out of attempts: surface the real error
                    sleep(base_delay * 2 ** attempt)
            raise AssertionError("unreachable")

        return wrapper

    return decorator


class LRUCache(Generic[K, V]):
    """8. Least-recently-used cache with O(1) get and put."""

    def __init__(self, capacity: int) -> None:
        if capacity < 1:
            raise ValueError("capacity must be >= 1")
        self._cap = capacity
        self._data: OrderedDict[K, V] = OrderedDict()

    def get(self, key: K, default: V | None = None) -> V | None:
        if key not in self._data:
            return default
        self._data.move_to_end(key)  # mark as most recently used
        return self._data[key]

    def put(self, key: K, value: V) -> None:
        self._data[key] = value
        self._data.move_to_end(key)
        if len(self._data) > self._cap:
            self._data.popitem(last=False)  # evict the least recently used

    def __len__(self) -> int:
        return len(self._data)


def test_c() -> None:
    calls: list[int] = []
    delays: list[float] = []

    @retry(attempts=3, base_delay=1.0, exceptions=(ConnectionError,), sleep=delays.append)
    def flaky() -> str:
        calls.append(1)
        if len(calls) < 3:
            raise ConnectionError("boom")
        return "ok"

    assert flaky() == "ok" and len(calls) == 3 and delays == [1.0, 2.0]
    assert flaky.__name__ == "flaky"

    @retry(attempts=2, sleep=lambda s: None, exceptions=(ConnectionError,))
    def wrong_error() -> None:
        raise KeyError("not retried")

    try:
        wrong_error()
        raise AssertionError("should raise")
    except KeyError:
        pass

    cache: LRUCache[str, int] = LRUCache(2)
    cache.put("a", 1)
    cache.put("b", 2)
    assert cache.get("a") == 1  # touches a, so b is now the oldest
    cache.put("c", 3)  # evicts b
    assert cache.get("b") is None and cache.get("a") == 1 and cache.get("c") == 3
    cache.put("a", 10)  # update in place, no growth
    assert len(cache) == 2 and cache.get("a") == 10

# exercises_d.py -- typed, generic code (exercises 9-10)
import math
from dataclasses import dataclass
from typing import Iterable, Iterator, Sequence, TypeVar

T = TypeVar("T")


def batched(items: Iterable[T], n: int) -> Iterator[list[T]]:
    """9. Yield lists of up to n items lazily (for example, embedding API batches)."""
    if n < 1:
        raise ValueError("n must be >= 1")
    batch: list[T] = []
    for item in items:
        batch.append(item)
        if len(batch) == n:
            yield batch
            batch = []
    if batch:
        yield batch


@dataclass(frozen=True)
class Hit:
    doc_id: str
    score: float


def cosine(a: Sequence[float], b: Sequence[float]) -> float:
    if len(a) != len(b):
        raise ValueError("dimension mismatch")
    dot = sum(x * y for x, y in zip(a, b))
    na, nb = math.sqrt(sum(x * x for x in a)), math.sqrt(sum(y * y for y in b))
    if na == 0 or nb == 0:
        return 0.0  # a zero vector has no direction; define similarity as 0
    return dot / (na * nb)


def top_k(query: Sequence[float], docs: dict[str, Sequence[float]], k: int) -> list[Hit]:
    """10. Brute-force nearest neighbours; ties broken by doc_id for determinism."""
    hits = [Hit(doc_id, cosine(query, vec)) for doc_id, vec in docs.items()]
    hits.sort(key=lambda h: (-h.score, h.doc_id))
    return hits[: max(k, 0)]


def test_d() -> None:
    gen = batched(range(5), 2)
    assert iter(gen) is gen  # a generator: lazy, single pass
    assert list(gen) == [[0, 1], [2, 3], [4]]
    assert list(batched([], 3)) == []
    try:
        list(batched([1], 0))  # the check runs on first next(), not at call time
        raise AssertionError("should raise")
    except ValueError:
        pass
    docs = {"x": [1.0, 0.0], "y": [0.0, 1.0], "z": [1.0, 1.0], "zero": [0.0, 0.0]}
    got = top_k([1.0, 0.0], docs, 3)
    assert [h.doc_id for h in got] == ["x", "z", "y"]  # y and zero tie at 0.0 -> "y" sorts first
    assert got[0].score == 1.0 and abs(got[1].score - math.sqrt(0.5)) < 1e-9
    assert top_k([1.0, 0.0], docs, 0) == []
    assert cosine([0, 0], [1, 2]) == 0.0

# llm.py -- the seam between your app and a model provider
import asyncio
import random
from collections.abc import AsyncGenerator, Awaitable, Callable
from typing import Protocol, TypeVar

T = TypeVar("T")


class LLMError(Exception):
    """Base class. `retryable` tells the retry helper whether trying again can help."""

    retryable = False


class LLMTimeout(LLMError):
    retryable = True


class LLMRateLimited(LLMError):
    retryable = True

    def __init__(self, retry_after: float | None = None) -> None:
        super().__init__("rate limited")
        self.retry_after = retry_after  # seconds, from a Retry-After header if present


class LLMBadRequest(LLMError):
    """A 4xx other than 429: the request itself is wrong, retrying will not fix it."""


class LLMClient(Protocol):
    async def complete(self, prompt: str) -> str: ...

    def stream(self, prompt: str) -> AsyncGenerator[str, None]: ...


class EchoLLM:
    """Offline stand-in so the app runs without a key. Replace with a real provider adapter."""

    async def complete(self, prompt: str) -> str:
        return f"echo: {prompt}"

    async def stream(self, prompt: str) -> AsyncGenerator[str, None]:
        for word in f"echo: {prompt}".split():
            yield word + " "
            await asyncio.sleep(0)


async def call_with_timeout(awaitable: Awaitable[T], seconds: float) -> T:
    """Hard deadline for one attempt. asyncio.timeout needs Python 3.11+."""
    try:
        async with asyncio.timeout(seconds):
            return await awaitable
    except TimeoutError as exc:
        raise LLMTimeout(f"no response within {seconds}s") from exc


async def retry_with_backoff(
    fn: Callable[[], Awaitable[T]],
    *,
    attempts: int = 4,
    base: float = 0.5,
    cap: float = 8.0,
    sleep: Callable[[float], Awaitable[None]] = asyncio.sleep,
    rng: Callable[[], float] = random.random,
) -> T:
    """Exponential backoff with full jitter. `fn` must create a fresh awaitable per attempt."""
    for attempt in range(attempts):
        try:
            return await fn()
        except LLMError as exc:
            if not exc.retryable or attempt == attempts - 1:
                raise
            delay = rng() * min(cap, base * 2 ** attempt)  # full jitter: uniform in [0, ceiling]
            if isinstance(exc, LLMRateLimited) and exc.retry_after is not None:
                delay = max(delay, exc.retry_after)  # never retry sooner than the server asked
            await sleep(delay)
    raise AssertionError("unreachable")

# main.py -- a small, testable FastAPI service in front of a model
import hmac
import json
import logging
import os
import uuid
from collections.abc import AsyncGenerator, Awaitable, Callable
from dataclasses import dataclass
from typing import Annotated, Any

import anyio
from fastapi import Depends, FastAPI, Header, Request
from fastapi.exceptions import RequestValidationError
from fastapi.responses import JSONResponse, StreamingResponse
from pydantic import BaseModel, Field

from llm import (EchoLLM, LLMClient, LLMError, LLMRateLimited, LLMTimeout,
                 call_with_timeout, retry_with_backoff)

log = logging.getLogger("api")


@dataclass(frozen=True)
class Settings:
    api_key: str
    timeout: float = 20.0
    attempts: int = 4
    retry_base: float = 0.5


def get_settings() -> Settings:
    return Settings(api_key=os.environ.get("API_KEY", "dev-key"))


def get_llm() -> LLMClient:
    return EchoLLM()  # swap for a real adapter; tests override this dependency


class ApiError(Exception):
    def __init__(self, status: int, code: str, message: str) -> None:
        self.status, self.code, self.message = status, code, message


def assign_request_id(request: Request, x_request_id: Annotated[str | None, Header()] = None) -> None:
    request.state.request_id = x_request_id or uuid.uuid4().hex[:12]


def require_api_key(
    settings: Annotated[Settings, Depends(get_settings)],
    x_api_key: Annotated[str | None, Header()] = None,
) -> None:
    supplied = (x_api_key or "").encode()
    if not hmac.compare_digest(supplied, settings.api_key.encode()):  # constant-time compare
        raise ApiError(401, "unauthorized", "missing or invalid API key")


class CompleteRequest(BaseModel):
    prompt: str = Field(min_length=1, max_length=4000)
    max_tokens: int = Field(default=256, ge=1, le=1024)


class CompleteResponse(BaseModel):
    text: str


app = FastAPI(title="mini-llm-api", dependencies=[Depends(assign_request_id)])


def error_body(request: Request, code: str, message: str, **extra: Any) -> dict[str, Any]:
    rid = getattr(request.state, "request_id", None)
    return {"error": {"code": code, "message": message, "request_id": rid, **extra}}


@app.exception_handler(ApiError)
async def on_api_error(request: Request, exc: ApiError) -> JSONResponse:
    return JSONResponse(error_body(request, exc.code, exc.message), status_code=exc.status)


@app.exception_handler(RequestValidationError)
async def on_validation(request: Request, exc: RequestValidationError) -> JSONResponse:
    fields = [{"loc": [str(p) for p in e["loc"]], "msg": e["msg"]} for e in exc.errors()]
    return JSONResponse(error_body(request, "invalid_request", "request validation failed", fields=fields), status_code=422)


@app.exception_handler(LLMError)
async def on_llm_error(request: Request, exc: LLMError) -> JSONResponse:
    log.warning("llm_error type=%s", type(exc).__name__)  # log the type, never the prompt
    if isinstance(exc, LLMRateLimited):
        headers = {"Retry-After": str(int(exc.retry_after or 1))}
        return JSONResponse(error_body(request, "upstream_rate_limited", "model provider is busy"), status_code=429, headers=headers)
    if isinstance(exc, LLMTimeout):
        return JSONResponse(error_body(request, "upstream_timeout", "model provider timed out"), status_code=504)
    return JSONResponse(error_body(request, "upstream_error", "model provider failed"), status_code=502)


SettingsDep = Annotated[Settings, Depends(get_settings)]
LLMDep = Annotated[LLMClient, Depends(get_llm)]


@app.post("/v1/complete", response_model=CompleteResponse, dependencies=[Depends(require_api_key)])
async def complete(body: CompleteRequest, llm: LLMDep, settings: SettingsDep) -> CompleteResponse:
    text = await retry_with_backoff(
        lambda: call_with_timeout(llm.complete(body.prompt), settings.timeout),
        attempts=settings.attempts,
        base=settings.retry_base,
    )
    return CompleteResponse(text=text)


def sse(event: str, data: dict[str, Any]) -> str:
    return f"event: {event}\ndata: {json.dumps(data)}\n\n"


async def sse_events(
    llm: LLMClient, prompt: str, max_tokens: int, is_disconnected: Callable[[], Awaitable[bool]]
) -> AsyncGenerator[str, None]:
    upstream = llm.stream(prompt)
    sent = 0
    try:
        async for piece in upstream:
            if await is_disconnected():
                return  # the finally block below still runs
            yield sse("token", {"text": piece})
            sent += 1
            if sent >= max_tokens:
                break
        yield sse("done", {"tokens": sent})
    except LLMError as exc:
        # Headers are already sent, so the status code cannot change: report in-band.
        yield sse("error", {"code": type(exc).__name__})
    finally:
        # Runs on normal end, error, and client disconnect (cancellation). Shield it so the
        # cleanup is not itself cancelled; closing the upstream stops generation (and billing).
        with anyio.CancelScope(shield=True):
            await upstream.aclose()


@app.post("/v1/stream", dependencies=[Depends(require_api_key)])
async def stream(body: CompleteRequest, request: Request, llm: LLMDep) -> StreamingResponse:
    events = sse_events(llm, body.prompt, body.max_tokens, request.is_disconnected)
    return StreamingResponse(
        events,
        media_type="text/event-stream",
        headers={"Cache-Control": "no-cache", "X-Accel-Buffering": "no"},  # no proxy buffering
    )

-- A race condition and three fixes. usage_quota(user_id, remaining) starts at (1, 1).
-- Default isolation in PostgreSQL is READ COMMITTED.

-- BROKEN: check-then-act across two statements.
--   Session A: BEGIN; SELECT remaining FROM usage_quota WHERE user_id = 1;   -- sees 1
--   Session B: BEGIN; SELECT remaining FROM usage_quota WHERE user_id = 1;   -- sees 1
--   Session A: UPDATE usage_quota SET remaining = 0 WHERE user_id = 1;  COMMIT;
--   Session B: UPDATE usage_quota SET remaining = 0 WHERE user_id = 1;  COMMIT;
--   Both callers were told "you have quota"; one unit was handed out twice.

-- FIX 1 (best here): one atomic statement. The row lock serialises the writers, and the second
-- one re-evaluates "remaining > 0" after the first commits, so it updates zero rows.
UPDATE usage_quota SET remaining = remaining - 1
WHERE user_id = 1 AND remaining > 0
RETURNING remaining;

-- FIX 2: lock the row while you read it, then decide.
BEGIN;
SELECT remaining FROM usage_quota WHERE user_id = 1 FOR UPDATE;   -- a second session waits here
UPDATE usage_quota SET remaining = remaining - 1 WHERE user_id = 1;
COMMIT;

-- FIX 3: stricter isolation, and the application retries on serialization failure (SQLSTATE 40001).
BEGIN ISOLATION LEVEL SERIALIZABLE;
SELECT remaining FROM usage_quota WHERE user_id = 1;
UPDATE usage_quota SET remaining = remaining - 1 WHERE user_id = 1;
COMMIT;   -- one of two concurrent transactions fails with 40001 and must be re-run

-- Isolation levels in PostgreSQL (check the docs for details):
--   READ COMMITTED   each statement sees data committed before that statement began (default).
--   REPEATABLE READ  the whole transaction sees one snapshot; concurrent updates to the same row error out.
--   SERIALIZABLE     behaves as if transactions ran one at a time; may abort with 40001, so always retry.
